/**
 * E2E test: Stripe spec CDN at stripe-sync.dev/openapi/stripe
 *
 * Verifies that:
 * 1. manifest.json is accessible and lists known spec versions
 * 2. resolveOpenApiSpec returns source:'cdn' for a non-bundled version
 *
 * No env vars required — hits the live CDN directly.
 * Tests are skipped automatically when the CDN isn't deployed yet (404).
 * Once deployed, any failure here means the CDN is broken.
 */
import os from 'node:os'
import path from 'node:path'
import { beforeAll, describe, it, expect } from 'vitest'
import { resolveOpenApiSpec, BUNDLED_API_VERSION } from '@stripe/sync-openapi'

const CDN_BASE = process.env.STRIPE_SPEC_CDN_BASE_URL ?? 'https://stripe-sync.dev/stripe-api-specs'

describe('Stripe spec CDN', () => {
  let manifest: Record<string, string> | null = null

  beforeAll(async () => {
    const res = await fetch(`${CDN_BASE}/manifest.json`).catch(() => null)
    if (!res || !res.ok) {
      console.warn(
        `Skipping CDN tests — ${CDN_BASE}/manifest.json returned ${res?.status ?? 'no response'} (CDN not deployed yet)`
      )
      return
    }
    manifest = (await res.json()) as Record<string, string>
  })

  it('manifest.json is reachable and lists spec versions', () => {
    if (!manifest) return // CDN not deployed yet

    const versions = Object.keys(manifest)
    expect(versions.length, 'manifest should list at least one version').toBeGreaterThan(0)

    for (const [version, filename] of Object.entries(manifest)) {
      expect(filename, `manifest entry for ${version}`).toMatch(/^.+\.json$/)
    }
  })

  it('each manifest entry resolves to a valid OpenAPI spec', async () => {
    if (!manifest) return // CDN not deployed yet

    // Spot-check the first 3 entries to keep the test fast
    const entries = Object.entries(manifest).slice(0, 3)
    for (const [version, filename] of entries) {
      const specRes = await fetch(`${CDN_BASE}/${filename}`)
      expect(specRes.status, `GET ${CDN_BASE}/${filename}`).toBe(200)

      const spec = (await specRes.json()) as Record<string, unknown>
      expect(typeof spec.openapi, `spec ${version} missing openapi field`).toBe('string')
      expect(spec.components, `spec ${version} missing components`).toBeTruthy()
    }
  })

  it('resolveOpenApiSpec uses cdn source for non-bundled version', async () => {
    if (!manifest) return // CDN not deployed yet

    // Find any version that isn't the bundled one
    const nonBundled = Object.keys(manifest).find(
      (v) => !v.startsWith(BUNDLED_API_VERSION.slice(0, 10))
    )
    if (!nonBundled) {
      console.warn('Only the bundled version is in the CDN manifest — skipping cdn source check')
      return
    }

    // Use an isolated cache dir so we don't hit a pre-existing cache entry
    const cacheDir = path.join(os.tmpdir(), `openapi-cdn-test-${Date.now()}`)
    const result = await resolveOpenApiSpec({ apiVersion: nonBundled, cacheDir }, fetch)

    expect(result.source).toBe('cdn')
    expect(result.apiVersion).toBe(nonBundled)
    expect(typeof result.spec.openapi).toBe('string')
  })
})

import { describe, it, expect } from 'vitest'
import { z } from 'zod'
import { OpenAPIHono, createRoute } from '../index.js'

const ItemSchema = z.object({
  id: z.string(),
  name: z.string(),
})

const ListSchema = z.object({
  data: z.array(ItemSchema),
  has_more: z.boolean(),
})

function createTestApp() {
  const app = new OpenAPIHono()

  app.openapi(
    createRoute({
      operationId: 'items.list',
      method: 'get',
      path: '/items',
      summary: 'List items',
      responses: {
        200: {
          content: { 'application/json': { schema: ListSchema } },
          description: 'List of items',
        },
      },
    }),
    (c) => {
      // Return invalid data (missing required 'name' on items)
      const query = c.req.query('mode')
      if (query === 'invalid') {
        return c.json({ data: [{ id: '1', extra: true }], has_more: false }, 200)
      }
      if (query === 'wrong-shape') {
        return c.json({ wrong: 'shape' }, 200)
      }
      return c.json({ data: [{ id: '1', name: 'Test' }], has_more: false }, 200)
    }
  )

  app.openapi(
    createRoute({
      operationId: 'items.get',
      method: 'get',
      path: '/items/{id}',
      summary: 'Get item',
      requestParams: { path: z.object({ id: z.string() }) },
      responses: {
        200: {
          content: { 'application/json': { schema: ItemSchema } },
          description: 'Single item',
        },
        404: {
          content: {
            'application/json': { schema: z.object({ error: z.string() }) },
          },
          description: 'Not found',
        },
      },
    }),
    (c) => {
      const { id } = c.req.valid('param')
      if (id === 'missing') {
        return c.json({ error: 'Not found' }, 404)
      }
      return c.json({ id, name: 'Item' }, 200)
    }
  )

  app.openapi(
    createRoute({
      operationId: 'items.delete',
      method: 'delete',
      path: '/items/{id}',
      summary: 'Delete item',
      requestParams: { path: z.object({ id: z.string() }) },
      responses: {
        204: {
          description: 'Deleted',
        },
      },
    }),
    (c) => {
      return c.body(null, 204)
    }
  )

  return app
}

describe('response validation', () => {
  it('passes valid responses through unchanged', async () => {
    const app = createTestApp()
    const res = await app.request('/items')
    expect(res.status).toBe(200)
    const body = await res.json()
    expect(body).toEqual({ data: [{ id: '1', name: 'Test' }], has_more: false })
  })

  it('returns 500 with error details for invalid response', async () => {
    const app = createTestApp()
    const res = await app.request('/items?mode=invalid')
    expect(res.status).toBe(500)
    const body = await res.json()
    expect(body.error).toBe('Response validation failed')
    expect(body.details).toBeDefined()
    expect(Array.isArray(body.details)).toBe(true)
  })

  it('returns 500 when response shape is completely wrong', async () => {
    const app = createTestApp()
    const res = await app.request('/items?mode=wrong-shape')
    expect(res.status).toBe(500)
    const body = await res.json()
    expect(body.error).toBe('Response validation failed')
  })

  it('validates different status codes with their own schemas', async () => {
    const app = createTestApp()
    const res = await app.request('/items/missing')
    expect(res.status).toBe(404)
    const body = await res.json()
    expect(body).toEqual({ error: 'Not found' })
  })

  it('skips validation for 204 No Content', async () => {
    const app = createTestApp()
    const res = await app.request('/items/123', { method: 'DELETE' })
    expect(res.status).toBe(204)
  })

  it('passes valid single-item response', async () => {
    const app = createTestApp()
    const res = await app.request('/items/abc')
    expect(res.status).toBe(200)
    const body = await res.json()
    expect(body).toEqual({ id: 'abc', name: 'Item' })
  })
})

import { execSync } from 'child_process'
import pg from 'pg'
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest'
import { acquire, createRateLimiterTable } from './rateLimiter.js'

// ---------------------------------------------------------------------------
// Docker Postgres lifecycle
// ---------------------------------------------------------------------------

let containerId: string
let pool: pg.Pool

beforeAll(async () => {
  containerId = execSync(
    'docker run -d --rm -p 0:5432 -e POSTGRES_PASSWORD=test -e POSTGRES_DB=test postgres:16-alpine',
    { encoding: 'utf8' }
  ).trim()

  const hostPort = execSync(`docker port ${containerId} 5432`, {
    encoding: 'utf8',
  })
    .trim()
    .split(':')
    .pop()

  pool = new pg.Pool({
    connectionString: `postgresql://postgres:test@localhost:${hostPort}/test`,
  })

  for (let i = 0; i < 30; i++) {
    try {
      await pool.query('SELECT 1')
      return
    } catch {
      await new Promise((r) => setTimeout(r, 1000))
    }
  }
  throw new Error('Postgres did not become ready in time')
}, 60_000)

afterAll(async () => {
  await pool?.end()
  if (containerId) {
    execSync(`docker rm -f ${containerId}`)
  }
})

// ---------------------------------------------------------------------------
// Fresh table per describe block
// ---------------------------------------------------------------------------

beforeEach(async () => {
  await pool.query('DROP TABLE IF EXISTS "_rate_limit_buckets"')
  await createRateLimiterTable(pool)
})

const opts = (max_rps = 10) => ({ key: 'test', max_rps })

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('basic acquire', () => {
  it('first acquire returns 0 (budget available)', async () => {
    const wait = await acquire(pool, opts())
    expect(wait).toBe(0)
  })

  it('exceeding one second of budget returns positive wait times', async () => {
    // max_rps=3 means 3 requests available per second
    const o = opts(3)

    // First 3 should be instant
    expect(await acquire(pool, o)).toBe(0)
    expect(await acquire(pool, o)).toBe(0)
    expect(await acquire(pool, o)).toBe(0)

    // 4th exceeds budget — should return a positive wait
    const wait = await acquire(pool, o)
    expect(wait).toBeGreaterThan(0)
  })

  it('returns correct wait time proportional to deficit', async () => {
    // max_rps=100 means 1 slot per 10ms
    const o = opts(100)

    // First acquire uses one slot
    expect(await acquire(pool, o)).toBe(0)

    // Drain remaining 99 slots
    for (let i = 0; i < 99; i++) await acquire(pool, o)

    // Next acquire: deficit ≈ 1, wait ≈ 1/100 = 0.01s
    const wait = await acquire(pool, o)
    expect(wait).toBeCloseTo(0.01, 1)
  })
})

describe('cost parameter', () => {
  it('deducts multiple slots at once', async () => {
    const o = opts(5)

    // Acquire all 5 slots at once — should succeed
    expect(await acquire(pool, o, 5)).toBe(0)

    // Next acquire should require waiting
    const wait = await acquire(pool, o, 1)
    expect(wait).toBeGreaterThan(0)
  })

  it('large cost on empty budget returns proportional wait', async () => {
    const o = opts(10)

    // Drain the budget
    await acquire(pool, o, 10)

    // Ask for 5 more: deficit ≈ 5, wait ≈ 5/10 = 0.5s
    const wait = await acquire(pool, o, 5)
    expect(wait).toBeCloseTo(0.5, 1)
  })
})

describe('refill', () => {
  it('slots refill over time', async () => {
    const o = opts(10)

    // Use all 10 slots
    await acquire(pool, o, 10)

    // Next acquire should need waiting (budget empty)
    const wait1 = await acquire(pool, o)
    expect(wait1).toBeGreaterThan(0)

    // Wait long enough to refill (300ms at 10/s = 3 slots, covers the 1 borrowed above)
    await new Promise((r) => setTimeout(r, 300))

    // Should have enough slots back
    const wait2 = await acquire(pool, o)
    expect(wait2).toBe(0)
  })

  it('budget caps at max_rps (no unbounded accumulation)', async () => {
    // Use a very low rate so inter-call time doesn't refill meaningfully
    const o = opts(0.01)

    // First call creates the bucket. Initial budget = max_rps = 0.01.
    // A single acquire with cost=1 exceeds that — should need waiting.
    const wait = await acquire(pool, o)
    expect(wait).toBeGreaterThan(0)
  })
})

describe('multiple keys', () => {
  it('independent keys have independent budgets', async () => {
    const a = opts(1)
    const b = { ...a, key: 'other' }

    expect(await acquire(pool, a)).toBe(0)
    expect(await acquire(pool, b)).toBe(0)

    // a is drained, b is drained — independently
    const waitA = await acquire(pool, a)
    const waitB = await acquire(pool, b)
    expect(waitA).toBeGreaterThan(0)
    expect(waitB).toBeGreaterThan(0)
  })
})

describe('concurrent workers', () => {
  it('serializes through advisory lock — total budget respected', async () => {
    const o = opts(5) // 5 rps, near-zero time between calls

    // Fire 10 concurrent acquires — at most 5 should be instant
    const results = await Promise.all(Array.from({ length: 10 }, () => acquire(pool, o)))

    const instant = results.filter((w) => w === 0).length
    const waited = results.filter((w) => w > 0).length
    expect(instant).toBe(5)
    expect(waited).toBe(5)
  })
})

describe('schema support', () => {
  it('works with a custom schema', async () => {
    await pool.query('CREATE SCHEMA IF NOT EXISTS "custom"')
    await pool.query('DROP TABLE IF EXISTS "custom"."_rate_limit_buckets"')
    await createRateLimiterTable(pool, 'custom')

    const o = { ...opts(), schema: 'custom' }
    expect(await acquire(pool, o)).toBe(0)
  })
})

